          type: 'object',
          properties: { lifetime_value: { type: 'number' } },
          required: ['lifetime_value'],
        },
        async handler(_args: unknown, _tctx: unknown) {
          return { ok: true as const, data: { lifetime_value: 9 } };
        },
      },
    });
  },
  onStop() {
    if (cancelTimer) { cancelTimer(); cancelTimer = null; }
